import{_ as e,o as i,c as d,ag as a}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"Miscellaneous JSON files","description":"","frontmatter":{},"headers":[],"relativePath":"Modders/Mod-file-structure/5-Miscellaneous-JSON-files.md","filePath":"Modders/Mod-file-structure/5-Miscellaneous-JSON-files.md"}'),s={name:"Modders/Mod-file-structure/5-Miscellaneous-JSON-files.md"};function o(n,t,r,l,h,u){return i(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="miscellaneous-json-files" tabindex="-1">Miscellaneous JSON files <a class="header-anchor" href="#miscellaneous-json-files" aria-label="Permalink to &quot;Miscellaneous JSON files&quot;">​</a></h1><h2 id="difficulties-json" tabindex="-1">Difficulties.json <a class="header-anchor" href="#difficulties-json" aria-label="Permalink to &quot;Difficulties.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/tree/master/android/assets/jsons/Civ%20V%20-%20Gods%20&amp;%20Kings/Difficulties.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This optional file defines the difficulty levels a player can choose when starting a new game.</p><p>Base ruleset Mods can omit the file or supply an empty list, even though at least one difficulty is mandatory, in which case they inherit <a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Vanilla/Difficulties.json" target="_blank" rel="noreferrer">the ones from the Vanilla ruleset</a>.</p><p>Each difficulty level has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>baseHappiness</td><td>Integer</td><td>0</td><td></td></tr><tr><td>extraHappinessPerLuxury</td><td>Float</td><td>0</td><td></td></tr><tr><td>researchCostModifier</td><td>Float</td><td>1</td><td></td></tr><tr><td>unitCostModifier</td><td>Float</td><td>1</td><td></td></tr><tr><td>unitSupplyBase</td><td>Integer</td><td>5</td><td></td></tr><tr><td>unitSupplyPerCity</td><td>Integer</td><td>2</td><td></td></tr><tr><td>buildingCostModifier</td><td>Float</td><td>1</td><td></td></tr><tr><td>policyCostModifier</td><td>Float</td><td>1</td><td></td></tr><tr><td>unhappinessModifier</td><td>Float</td><td>1</td><td></td></tr><tr><td>barbarianBonus</td><td>Float</td><td>0</td><td></td></tr><tr><td>barbarianSpawnDelay</td><td>Integer</td><td>0</td><td></td></tr><tr><td>playerBonusStartingUnits</td><td>List of Strings</td><td>empty</td><td>Can also be &#39;Era Starting Unit&#39;, maps to <code>startingMilitaryUnit</code> of the Eras file. All other units must be in <a href="./4-Unit-related-JSON-files.html#units-json">Units.json</a>. Applies only to human player civs</td></tr><tr><td>aiDifficultyLevel</td><td>String</td><td>empty</td><td>Applies some modifiers to the AI from the chosen difficulty. Modifiers such as unhappinessModifier and aiUnhappinessModifier stack multiplicatively. If empty: defaults to &quot;Chieftain&quot;, or the first available difficulty.</td></tr><tr><td>aiCityGrowthModifier</td><td>Float</td><td>1</td><td></td></tr><tr><td>aiUnitCostModifier</td><td>Float</td><td>1</td><td></td></tr><tr><td>aiBuildingCostModifier</td><td>Float</td><td>1</td><td></td></tr><tr><td>aiWonderCostModifier</td><td>Float</td><td>1</td><td></td></tr><tr><td>aiBuildingMaintenanceModifier</td><td>Float</td><td>1</td><td></td></tr><tr><td>aiUnitMaintenanceModifier</td><td>Float</td><td>1</td><td></td></tr><tr><td>aiUnitSupplyModifier</td><td>Integer</td><td>5</td><td></td></tr><tr><td>aiFreeTechs</td><td>List of Strings</td><td>empty</td><td>Must be in <a href="./2-Civilization-related-JSON-files.html#techs-json">Techs.json</a></td></tr><tr><td>aiMajorCivBonusStartingUnits</td><td>List of Strings</td><td>empty</td><td>Same rules as playerBonusStartingUnits, See above. Applies only to AI major civs</td></tr><tr><td>aiCityStateBonusStartingUnits</td><td>List of Strings</td><td>empty</td><td>Same rules as playerBonusStartingUnits, See above. Applies only to city-state civs</td></tr><tr><td>aiUnhappinessModifier</td><td>Float</td><td>1</td><td></td></tr><tr><td>turnBarbariansCanEnterPlayerTiles</td><td>Integer</td><td>0</td><td></td></tr><tr><td>clearBarbarianCampReward</td><td>Integer</td><td>25</td><td></td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>Will be treated as part of GlobalUniques when this difficulty is chosen</td></tr></tbody></table><h2 id="eras-json" tabindex="-1">Eras.json <a class="header-anchor" href="#eras-json" aria-label="Permalink to &quot;Eras.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/tree/master/android/assets/jsons/Civ%20V%20-%20Gods%20&amp;%20Kings/Eras.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This file should contain all the era&#39;s you want to use in your mod.</p><p>Each era can have the following attributes:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td></td></tr><tr><td>researchAgreementCost</td><td>Integer (≥0)</td><td>300</td><td>Cost of research agreements when the most technologically advanced civ is in this era</td></tr><tr><td>iconRGB</td><td><a href="#rgb-colors-list">List of 3× Integer</a></td><td>white</td><td>RGB color that icons for technologies of this era should have in the Tech screen</td></tr><tr><td>startingSettlerCount</td><td>Integer (≥0)</td><td>1</td><td>Amount of settler units that should be spawned when starting a game in this era (setting this to zero is discouraged [^1])</td></tr><tr><td>startingSettlerUnit</td><td>String</td><td>&quot;Settler&quot;</td><td>Name of the unit that should be used for the previous field. Must be in <a href="./4-Unit-related-JSON-files.html#units-json">Units.json</a>, or a unit with the &quot;Founds a new city&quot; unique must exist</td></tr><tr><td>startingWorkerCount</td><td>Integer (≥0)</td><td>0</td><td>Amount of worker units that should be spawned when starting a game in this era</td></tr><tr><td>startingWorkerUnit</td><td>String</td><td>&quot;Worker&quot;</td><td>Name of the unit that should be used for the previous field. If startingWorkerCount&gt;0, then it must exist in <a href="./4-Unit-related-JSON-files.html#units-json">Units.json</a>, or a unit with the &quot;Can build [filter] improvements on tiles&quot; unique must exist</td></tr><tr><td>startingMilitaryUnitCount</td><td>Integer (≥0)</td><td>1</td><td>Amount of military units that should be spawned when starting a game in this era</td></tr><tr><td>startingMilitaryUnit</td><td>String</td><td>&quot;Warrior&quot;</td><td>Name of the unit that should be used for the previous field. Must be in <a href="./4-Unit-related-JSON-files.html#units-json">Units.json</a></td></tr><tr><td>startingGold</td><td>Integer (≥0)</td><td>0</td><td>Amount of gold each civ should receive when starting a game in this era</td></tr><tr><td>startingCulture</td><td>Integer (≥0)</td><td>0</td><td>Amount of culture each civ should receive when starting a game in this era</td></tr><tr><td>settlerPopulation</td><td>Integer (&gt;0)</td><td>1</td><td>Amount of population each city should have when settled when starting a game in this era</td></tr><tr><td>settlerBuildings</td><td>List of Strings</td><td>empty</td><td>Buildings that should automatically be built whenever a city is settled when starting a game in this era</td></tr><tr><td>startingObsoleteWonders</td><td>List of Strings</td><td>empty</td><td>Wonders (and technically buildings) that should be impossible to built when starting a game in this era. Used in the base game to remove all wonders older than 2 era&#39;s</td></tr><tr><td>baseUnitBuyCost</td><td>Integer</td><td>200</td><td>Default value used for the unique <code>Can be purchased with [stat] [cityFilter]</code></td></tr><tr><td>embarkDefense</td><td>Integer</td><td>3</td><td>Default defense for embarked unit in this era</td></tr><tr><td>startPercent</td><td>Integer</td><td>0</td><td>When starting, percentage ([0]%-[100]%) of turns skipped in total turns specified in <a href="#speeds-json">Speed.json</a></td></tr><tr><td>citySound</td><td>String</td><td>&quot;cityClassical&quot;</td><td>Sound used when city is founded in this era</td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>Will be treated as part of GlobalUniques when starting in this era</td></tr></tbody></table><p>[^1]: Successfully setting startingSettlerCount to zero in a mod (idea: conquer or die) is not easy. Some player-controlled settings require at least one Settler, through any source (see difficulties for other possible settler sources), or you won&#39;t be able to start a game: Once City Challenge requires one for all players, and allowing any city-states requires one for those. Would also affect defeat rules.</p><h2 id="speeds-json" tabindex="-1">Speeds.json <a class="header-anchor" href="#speeds-json" aria-label="Permalink to &quot;Speeds.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/tree/master/android/assets/jsons/Civ%20V%20-%20Gods%20&amp;%20Kings/Speeds.json" target="_blank" rel="noreferrer">Link to original</a></p><p>This optional file should contain all the speeds you want to use in your mod.</p><p>Base ruleset Mods can omit the file or supply an empty list, even though at least one game speed is mandatory, in which case they inherit <a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Vanilla/Speeds.json" target="_blank" rel="noreferrer">the ones from the Vanilla ruleset</a>.</p><p>Each speed can have the following attributes:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td>Name of the speed</td></tr><tr><td>modifier</td><td>Float (≥0)</td><td>1.0</td><td>Overall game speed modifier</td></tr><tr><td>productionCostModifier</td><td>Float (≥0)</td><td><code>modifier</code> value</td><td>Scales production cost of units and buildings</td></tr><tr><td>goldCostModifier</td><td>Float (≥0)</td><td><code>modifier</code> value</td><td>Scales gold costs</td></tr><tr><td>scienceCostModifier</td><td>Float (≥0)</td><td><code>modifier</code> value</td><td>Scales science costs</td></tr><tr><td>cultureCostModifier</td><td>Float (≥0)</td><td><code>modifier</code> value</td><td>Scales culture costs</td></tr><tr><td>faithCostModifier</td><td>Float (≥0)</td><td><code>modifier</code> value</td><td>Scales faith costs</td></tr><tr><td>improvementBuildLengthModifier</td><td>Float (≥0)</td><td><code>modifier</code> value</td><td>Scales the time it takes for a worker to build tile improvements</td></tr><tr><td>barbarianModifier</td><td>Float (≥0)</td><td><code>modifier</code> value</td><td>Scales the time between barbarian spawns</td></tr><tr><td>goldGiftModifier</td><td>Float (≥0)</td><td><code>modifier</code> value</td><td>Scales the influence gained from gifting gold to city-states</td></tr><tr><td>cityStateTributeScalingInterval</td><td>Float (≥0)</td><td>6.5</td><td>The number of turns it takes for the amount of gold a player demands from city-states to increase by 5 gold</td></tr><tr><td>goldenAgeLengthModifier</td><td>Float (≥0)</td><td><code>modifier</code> value</td><td>Scales the length of golden ages</td></tr><tr><td>religiousPressureAdjacentCity</td><td>Integer (≥0)</td><td>6</td><td>Defines how much religious pressure a city exerts on nearby cities</td></tr><tr><td>peaceDealDuration</td><td>Integer (≥0)</td><td>10</td><td>The number of turns a peace deal lasts</td></tr><tr><td>dealDuration</td><td>Integer (≥0)</td><td>30</td><td>The number of turns a non-peace deal (research agreement, open borders, etc.) lasts</td></tr><tr><td>startYear</td><td>Float</td><td>-4000</td><td>The start year of the game (negative is BC/BCE)</td></tr><tr><td>turns</td><td>List</td><td>Required</td><td>List of time interval per turn, <a href="#time-interval-per-turn">see below</a></td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>Will be treated as part of GlobalUniques when this speed is chosen</td></tr></tbody></table><h3 id="time-interval-per-turn" tabindex="-1">Time interval per turn <a class="header-anchor" href="#time-interval-per-turn" aria-label="Permalink to &quot;Time interval per turn&quot;">​</a></h3><p>The &quot;turns&quot; attribute defines the number of years passing between turns. The attribute consists of a list of objects, each having 2 required attributes: &quot;yearsPerTurn&quot; (Float) and &quot;untilTurn&quot; (Integer)</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>yearsPerTurn</td><td>Integer</td><td>Required</td><td>Number of years passing between turns</td></tr><tr><td>untilTurn</td><td>Integer</td><td>Required</td><td>End of this interval (if it is the last object, see below)</td></tr></tbody></table><p>For each row, &quot;yearsPerTurn&quot; is applied up to the &quot;untilTurn&quot;-1 to &quot;untilTurn&quot; step. The last &quot;untilTurn&quot; in the list is ignored for year calculation, that is, if a game passes that turn number, years continue to increment by the &quot;yearsPerTurn&quot; of the last entry. However, this is used when starting a game in a later Era: Era.startPercent is relative to the last &quot;untilTurn&quot;.</p><p>The code below is an example of a valid &quot;turns&quot; definition and it specifies that the first 50 turns of a game last for 60 years each, then the next 30 turns (and any played after the 80th) last for 40 years each.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;turns&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;yearsPerTurn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;untilTurn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;yearsPerTurn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;untilTurn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:  </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="events-json" tabindex="-1">Events.json <a class="header-anchor" href="#events-json" aria-label="Permalink to &quot;Events.json&quot;">​</a></h2><p>Events allow users to choose between options of triggers to activate.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td>Used for triggering via &quot;Triggers a [event] event&quot; unique</td></tr><tr><td>text</td><td>String</td><td>None</td><td>Flavor text displayed to user</td></tr><tr><td>presentation</td><td>One of: &quot;None&quot;, &quot;Alert&quot;, &quot;Floating&quot;</td><td>Alert</td><td>&quot;Alert&quot; indicates a regular popup, &quot;None&quot; means the choice is made randomly, &quot;Floating&quot; is for tutorial-style indicators</td></tr><tr><td>civilopediaText</td><td>List</td><td>Optional</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr><tr><td>choices</td><td>List of EventChoices</td><td></td><td>User can choose to trigger one of the viable choices</td></tr></tbody></table><p>You can use text and/or civilopediaText, if both are present both are shown (but why would you?)</p><p>Event choices are comprised of:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>text</td><td>String</td><td>Required</td><td>Displayed to user as button. Should be an action name - &quot;Do X&quot;</td></tr><tr><td>uniques</td><td>List of uniques to trigger or limit conditions</td><td>Required</td><td>The triggers that this choice activates upon being chosen, and &quot;Unavailable&quot; / &quot;Only available&quot; uniques</td></tr><tr><td>keyShortcut</td><td>key to select (name)</td><td>none</td><td>Key names see <a href="https://github.com/libgdx/libgdx/blob/master/gdx/src/com/badlogic/gdx/Input.java#L69" target="_blank" rel="noreferrer">Gdx.Input.Keys</a></td></tr><tr><td>civilopediaText</td><td>List</td><td>Optional</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><p>Here, civilopediaText is shown outside the active Button, before the triggeredUniques.</p><h2 id="modoptions-json" tabindex="-1">ModOptions.json <a class="header-anchor" href="#modoptions-json" aria-label="Permalink to &quot;ModOptions.json&quot;">​</a></h2><p>This file is a little different:</p><ul><li>Does not exist in Vanilla ruleset</li><li>Is entirely optional but will be created after downloading a mod</li></ul><p>Note that this file controls <em>declarative mod compatibility</em> (Work in progress) - e.g. there&#39;s <a href="./../uniques.html#modoptions-uniques">uniques</a> to say your Mod should only or never be used as &#39;Permanent audiovisual mod&#39;. Incompatibility filtering works so far between extension and base mods, but feel free to document known extension-to-extension incompatibilities using the same Unique now. Stay tuned!</p><p>The file can have the following attributes, not including the values Unciv sets automatically:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>default</th><th>Notes</th></tr></thead><tbody><tr><td>isBaseRuleset</td><td>Boolean</td><td>false</td><td>Replaces vanilla ruleset if true</td></tr><tr><td>uniques</td><td>List</td><td>empty</td><td>Mod-wide specials, <a href="./../uniques.html#modoptions-uniques">see here</a></td></tr><tr><td>techsToRemove</td><td>List</td><td>empty</td><td>List of <a href="./2-Civilization-related-JSON-files.html#techs-json">Technologies</a> or <a href="./../Unique-parameters.html#technologyfilter">technologyFilter</a> to remove (isBaseRuleset=false only)</td></tr><tr><td>buildingsToRemove</td><td>List</td><td>empty</td><td>List of <a href="./2-Civilization-related-JSON-files.html#buildings-json">Buildings or Wonders</a> or <a href="./../Unique-parameters.html#buildingfilter">buildingFilter</a> to remove (isBaseRuleset=false only)</td></tr><tr><td>unitsToRemove</td><td>List</td><td>empty</td><td>List of <a href="./4-Unit-related-JSON-files.html#units-json">Units</a> or <a href="./../Unique-parameters.html#baseunitfilter">unitFilter</a> to remove (isBaseRuleset=false only)</td></tr><tr><td>nationsToRemove</td><td>List</td><td>empty</td><td>List of <a href="./2-Civilization-related-JSON-files.html#nations-json">Nations</a> or <a href="./../Unique-parameters.html#nationfilter">nationFilter</a> to remove (isBaseRuleset=false only)</td></tr><tr><td>policyBranchesToRemove</td><td>List</td><td>empty</td><td>List of <a href="./2-Civilization-related-JSON-files.html#policies-json">Policy Branches</a> to remove (isBaseRuleset=false only)</td></tr><tr><td>policiesToRemove</td><td>List</td><td>empty</td><td>List of <a href="./2-Civilization-related-JSON-files.html#policies-json">Policies</a> to remove (isBaseRuleset=false only)</td></tr><tr><td>beliefsToRemove</td><td>List</td><td>empty</td><td>List of <a href="./2-Civilization-related-JSON-files.html#beliefs-json">Beliefs</a> to remove (isBaseRuleset=false only)</td></tr><tr><td>religionsToRemove</td><td>List</td><td>empty</td><td>List of <a href="./2-Civilization-related-JSON-files.html#religions-json">Religions</a> to remove (isBaseRuleset=false only)</td></tr><tr><td>constants</td><td>Object</td><td>empty</td><td>See <a href="#modconstants">ModConstants</a></td></tr><tr><td>tileset</td><td>String</td><td>empty</td><td>Only applicable for base rulesets</td></tr><tr><td>unitset</td><td>String</td><td>empty</td><td>Only applicable for base rulesets</td></tr></tbody></table><p>The values normally set automatically from github metadata are:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th></th><th>Notes</th></tr></thead><tbody><tr><td>modUrl</td><td>String</td><td></td><td>The github page the mod was downloaded from, or empty if a freely hosted zip was used</td></tr><tr><td>defaultBranch</td><td>String</td><td>master</td><td>The repo&#39;s default branch</td></tr><tr><td>author</td><td>String</td><td></td><td>Repo owner</td></tr><tr><td>lastUpdated</td><td>String</td><td></td><td>ISO date</td></tr><tr><td>modSize</td><td>Integer</td><td>0</td><td>Size in kB</td></tr><tr><td>topics</td><td>List</td><td>empty</td><td>A list of &quot;unciv-mod-*&quot; github topics</td></tr></tbody></table><p>To clarify: When your Mod is distributed via github, including these in the Mod repo has no effect. However, when a Mod is distributed <em>without</em> a github repository, these values can and <em>should</em> be set by the author in the distributed <code>ModOptions.json</code>.</p><h3 id="version-requirements-uncivcn" tabindex="-1">Version requirements (UncivCN) <a class="header-anchor" href="#version-requirements-uncivcn" aria-label="Permalink to &quot;Version requirements (UncivCN)&quot;">​</a></h3><p>Mods can declare a version and compatibility requirements, which are checked with warnings (never blocking) when the mod is used:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>modVersion</td><td>String</td><td>0.0.1</td><td>Mod version in <code>n.n.n</code> format; shown in the mod manager and used for dependency version checks</td></tr><tr><td>recommendedGameVersion</td><td>String</td><td>empty</td><td>The game version this mod version was made for, exact match (<code>n.n.n</code>, <code>n.n.n.n</code> or <code>-patchN</code> suffix); empty = not declared</td></tr><tr><td>modDependencies</td><td>List</td><td>empty</td><td>Dependency mods, each an object <code>{ &quot;name&quot;: ..., &quot;recommendedVersion&quot;: ... }</code>; <code>recommendedVersion</code> is the exact version the dependency should have (exact match), empty = any version</td></tr></tbody></table><p>Example:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;modVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;recommendedGameVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;4.21.7.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;modDependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;UCCC&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;recommendedVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.5.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MyOtherMod&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;recommendedVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;3.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h4 id="when-are-warnings-shown" tabindex="-1">When are warnings shown? <a class="header-anchor" href="#when-are-warnings-shown" aria-label="Permalink to &quot;When are warnings shown?&quot;">​</a></h4><ul><li><strong>Game version</strong>: when the current game version does not exactly match <code>recommendedGameVersion</code>, e.g. the mod declares <code>recommendedGameVersion: &quot;4.21.7.1&quot;</code> and the player runs 4.21.7.2 — the mod manager shows the version and the recommended game version right in the installed mod list, a warning mark next to the mod and a yellow warning line in the info pane, the new-game mod selection shows a toast, and the mod checker (Options → Locate mod errors) lists the warning.</li><li><strong>Dependencies</strong>: when a dependency mod is not loaded at all, or its <code>modVersion</code> does not exactly match the declared <code>recommendedVersion</code>.</li><li><strong>Invalid declarations</strong>: typos in the version or range format are also reported, so authors notice and fix them.</li></ul><p>In all cases the mod stays usable - warnings never block anything.</p><p><code>recommendedGameVersion</code> says &quot;this mod version was made for game version X&quot; - it shows up directly in the mod manager (e.g. <code>Version 0.1.0 · game 4.21.7.1</code>) and the warning text reads as a recommendation rather than a requirement. Leave it empty when the mod works on all game versions.</p><h4 id="version-format-details" tabindex="-1">Version format details <a class="header-anchor" href="#version-format-details" aria-label="Permalink to &quot;Version format details&quot;">​</a></h4><ul><li>Any number of dot-separated numeric segments is accepted (<code>1</code>, <code>1.2</code>, <code>1.2.3</code>, <code>4.21.5.3</code>), though <code>n.n.n</code> is recommended for <code>modVersion</code>.</li><li>An optional <code>-patchN</code> suffix is supported and compares as an extra segment: <code>4.21.5.3</code> &lt; <code>4.21.5.3-patch1</code> &lt; <code>4.21.5.3-patch2</code> &lt; <code>4.21.6</code>.</li><li>Shorter versions compare as if padded with zeros: <code>1.2</code> == <code>1.2.0</code>.</li><li>A dependency without a <code>recommendedVersion</code> accepts any version of that mod.</li></ul><h4 id="relation-to-the-modrequires-modincompatiblewith-uniques" tabindex="-1">Relation to the <code>ModRequires</code> / <code>ModIncompatibleWith</code> uniques <a class="header-anchor" href="#relation-to-the-modrequires-modincompatiblewith-uniques" aria-label="Permalink to &quot;Relation to the \`ModRequires\` / \`ModIncompatibleWith\` uniques&quot;">​</a></h4><p>Unciv already has declarative mod compatibility uniques (<code>ModRequires</code>, <code>ModIncompatibleWith</code>): when they are not satisfied, the mod is <strong>not selectable</strong> in the mod selection. The version requirements above are a softer, UncivCN-specific layer: unsatisfied requirements only produce <strong>warnings</strong>. Use <code>ModRequires</code> to say &quot;this mod needs another mod to function&quot;, and <code>modDependencies</code> to also recommend a specific version of the dependency.</p><h4 id="good-practice" tabindex="-1">Good practice <a class="header-anchor" href="#good-practice" aria-label="Permalink to &quot;Good practice&quot;">​</a></h4><ul><li>Bump <code>modVersion</code> on every release, so dependency version checks stay meaningful.</li><li>Use <code>recommendedGameVersion</code> to pin the game version a mod version was made for (exact match); leave it empty when the mod works on all game versions.</li></ul><div class="custom-block note"><p>As an alternative to the <code>*ToRemove</code> lists, you can use <a href="./6-MergeActions.html">Merge Actions</a> with <code>&quot;action&quot;: &quot;REMOVE&quot;</code> directly in the corresponding JSON file (e.g. <code>{ &quot;name&quot;: &quot;Scout&quot;, &quot;_mergeAction&quot;: { &quot;action&quot;: &quot;REMOVE&quot; } }</code> in <code>Units.json</code>). This keeps the removal declaration alongside the data it relates to, and also supports conditions (<code>&quot;if&quot;</code>). Both methods are supported and can be used together.</p></div><h3 id="modconstants" tabindex="-1">ModConstants <a class="header-anchor" href="#modconstants" aria-label="Permalink to &quot;ModConstants&quot;">​</a></h3><p>Stored in ModOptions.constants, this is a collection of constants used internally in Unciv. This is the only structure that is <em>merged</em> field by field from mods, not overwritten, so you can change XP from Barbarians in one mod and city distance in another. In case of conflicts, there is no guarantee which mod wins, only that <em>default</em> values are ignored.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>maxXPfromBarbarians</td><td>Int</td><td>30</td><td>[^A]</td></tr><tr><td>cityStrengthBase</td><td>Float</td><td>8.0</td><td>[^B]</td></tr><tr><td>cityStrengthPerPop</td><td>Float</td><td>0.4</td><td>[^B]</td></tr><tr><td>cityStrengthFromTechsMultiplier</td><td>Float</td><td>5.5</td><td>[^B]</td></tr><tr><td>cityStrengthFromTechsExponent</td><td>Float</td><td>2.8</td><td>[^B]</td></tr><tr><td>cityStrengthFromTechsFullMultiplier</td><td>Float</td><td>1.0</td><td>[^B]</td></tr><tr><td>cityStrengthFromGarrison</td><td>Float</td><td>0.2</td><td>[^B]</td></tr><tr><td>baseCityBombardRange</td><td>Int</td><td>2</td><td>[^S]</td></tr><tr><td>cityWorkRange</td><td>Int</td><td>3</td><td>[^T]</td></tr><tr><td>cityExpandRange</td><td>Int</td><td>5</td><td>[^U]</td></tr><tr><td>cityAirUnitCapacity</td><td>Int</td><td>6</td><td>[^W]</td></tr><tr><td>unitSupplyPerPopulation</td><td>Float</td><td>0.5</td><td>[^C]</td></tr><tr><td>minimalCityDistance</td><td>Int</td><td>3</td><td>[^D]</td></tr><tr><td>minimalCityDistanceOnDifferentContinents</td><td>Int</td><td>2</td><td>[^D]</td></tr><tr><td>unitUpgradeCost</td><td>Object</td><td><a href="#unitupgradecost">See below</a></td><td>[^J]</td></tr><tr><td>naturalWonderCountMultiplier</td><td>Float</td><td>0.124</td><td>[^E]</td></tr><tr><td>naturalWonderCountAddedConstant</td><td>Float</td><td>0.1</td><td>[^E]</td></tr><tr><td>ancientRuinCountMultiplier</td><td>Float</td><td>0.02</td><td>[^F]</td></tr><tr><td>spawnIceBelowTemperature</td><td>Float</td><td>-0.8</td><td>[^G]</td></tr><tr><td>maxLakeSize</td><td>Int</td><td>10</td><td>[^H]</td></tr><tr><td>riverCountMultiplier</td><td>Float</td><td>0.01</td><td>[^I]</td></tr><tr><td>minRiverLength</td><td>Int</td><td>5</td><td>[^I]</td></tr><tr><td>maxRiverLength</td><td>Int</td><td>666</td><td>[^I]</td></tr><tr><td>religionLimitBase</td><td>Int</td><td>1</td><td>[^K]</td></tr><tr><td>religionLimitMultiplier</td><td>Float</td><td>0.5</td><td>[^K]</td></tr><tr><td>pantheonBase</td><td>Int</td><td>10</td><td>[^L]</td></tr><tr><td>pantheonGrowth</td><td>Int</td><td>5</td><td>[^L]</td></tr><tr><td>workboatAutomationSearchMaxTiles</td><td>Int</td><td>20</td><td>[^M]</td></tr><tr><td>maxSpyRank</td><td>Int</td><td>3</td><td>[^N]</td></tr><tr><td>spyRankSkillPercentBonus</td><td>Float</td><td>30</td><td>[^O]</td></tr><tr><td>minimumWarDuration</td><td>Int</td><td>10</td><td>[^P]</td></tr><tr><td>baseTurnsUntilRevolt</td><td>Int</td><td>4</td><td>[^Q]</td></tr><tr><td>cityStateElectionTurns</td><td>Int</td><td>15</td><td>[^R]</td></tr><tr><td>maxImprovementTechErasForward</td><td>Int</td><td>None</td><td>[^S]</td></tr><tr><td>goldGiftMultiplier</td><td>Float</td><td>1</td><td>[^T]</td></tr><tr><td>goldGiftTradeMultiplier</td><td>Float</td><td>0.8</td><td>[^U]</td></tr><tr><td>goldGiftDegradationMultiplier</td><td>Float</td><td>1.0</td><td>[^V]</td></tr></tbody></table><p>Legend:</p><ul><li>[^A]: Max amount of experience that can be gained from combat with barbarians</li><li>[^B]: Formula for city Strength: Strength = baseStrength + strengthPerPop + strengthFromTiles + ((%techs * multiplier) ^ exponent) * fullMultiplier + (garrisonBonus * garrisonUnitStrength * garrisonUnitHealth/garrisonUnitMaxHealth) + defensiveBuildingStrength where %techs is the percentage of techs in the tech tree that are complete garrisonUnitHealth is the garrisoned unit&#39;s current HP and garrisonUnitMaxHealth its max HP (moddable, default 100) - the ratio is its HP percentage If no techs exist in this ruleset, %techs = 0.5 (=50%)</li><li>[^S]: The distance that cities can attack. Minimum 0.</li><li>[^T]: The tiles in distance that population in cities can work on. Note: Higher values may lead to performace issues and may cause bugs. cityWorkRange may be greater than cityExpandRange. Minimum 1, maximum 100.</li><li>[^U]: The distance that cities can expand their borders to. Note: Higher values may lead to performace issues and may cause bugs. Minimum 1, maximum 100.</li><li>[^C]: Formula for Unit Supply: Supply = unitSupplyBase (difficulties.json) unitSupplyPerCity * amountOfCities + (difficulties.json) unitSupplyPerPopulation * amountOfPopulationInAllCities unitSupplyBase and unitSupplyPerCity can be found in difficulties.json unitSupplyBase, unitSupplyPerCity and unitSupplyPerPopulation can also be increased through uniques</li><li>[^D]: The minimal distance that must be between any two cities, not counting the tiles cities are on The number is the amount of tiles between two cities, not counting the tiles the cities are on. e.g. &quot;C__C&quot;, where &quot;C&quot; is a tile with a city and &quot;_&quot; is a tile without a city, has a distance of 2. First constant is for cities on the same landmass, the second is for cities on different continents. Minimum 0.</li><li>[^E]: NaturalWonderGenerator uses these to determine the number of Natural Wonders to spawn for a given map size. The number scales linearly with map radius: #wonders = radius * naturalWonderCountMultiplier + naturalWonderCountAddedConstant. The defaults effectively mean Tiny - 1, Small - 2, Medium - 3, Large - 4, Huge - 5, Custom radius &gt;=109 - all G&amp;K wonders.</li><li>[^F]: MapGenerator.spreadAncientRuins: number of ruins = suitable tile count * this</li><li>[^G]: MapGenerator.spawnIce: spawn Ice where T &lt; this, with T calculated from temperatureExtremeness, latitude and perlin noise.</li><li>[^H]: MapGenerator.spawnLakesAndCoasts: Water bodies up to this tile count become Lakes</li><li>[^I]: RiverGenerator: river frequency and length bounds</li><li>[^J]: A <a href="#unitupgradecost">UnitUpgradeCost</a> sub-structure.</li><li>[^K]: Maximum foundable Religions = religionLimitBase + floor(MajorCivCount * religionLimitMultiplier)</li><li>[^L]: Cost of pantheon = pantheonBase + CivsWithReligion * pantheonGrowth</li><li>[^M]: When the AI decides whether to build a work boat, how many tiles to search from the city center for an improvable tile</li><li>[^N]: The maximum rank any spy can reach</li><li>[^O]: How much skill bonus each rank gives</li><li>[^P]: The number of turns a civ has to wait before negotiating for peace</li><li>[^Q]: The number of turns before a revolt is spawned</li><li>[^R]: The number of turns between city-state elections</li><li>[^S]: If set, the Improvement picker will silently skip improvements whose tech requirement is more advanced than your current Era + this value. Example: With a 0, Trade posts will not show until the Medieval Era, with a 1 they will already show in the CLassical Era.</li><li>[^T]: The multiplier of the gold value of a one-sided trade to be stored as gifts.</li><li>[^U]: The multiplier of the gold value of a regular trade to be stored as gifts. Set to 0 to disable gold gifting in two-sided trades.</li><li>[^U]: Modifies how quickly the GaveUsGifts dimplomacy modifier runs out. A higher value makes it run out quicker. Normally the gifts reduced by ~2.5% per turn depending on the diplomatic relations with the default value.</li><li>[^W]: Number of air units that can be stationed in a city, not including carried/transported air units.</li></ul><h4 id="unitupgradecost" tabindex="-1">UnitUpgradeCost <a class="header-anchor" href="#unitupgradecost" aria-label="Permalink to &quot;UnitUpgradeCost&quot;">​</a></h4><p>These values are not merged individually, only the entire sub-structure is.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th></th><th>Notes</th></tr></thead><tbody><tr><td>base</td><td>Float</td><td>10</td><td></td></tr><tr><td>perProduction</td><td>Float</td><td>2</td><td></td></tr><tr><td>eraMultiplier</td><td>Float</td><td>0</td><td></td></tr><tr><td>exponent</td><td>Float</td><td>1</td><td></td></tr><tr><td>roundTo</td><td>Int</td><td>5</td><td></td></tr></tbody></table><p>The formula for the gold cost of a unit upgrade is (rounded down to a multiple of <code>roundTo</code>): ( max((<code>base</code> + <code>perProduction</code> * (new_unit_cost - old_unit_cost)), 0) * (1 + eraNumber * <code>eraMultiplier</code>) * <code>civModifier</code> ) ^ <code>exponent</code> With <code>civModifier</code> being the multiplicative aggregate of <a href="./../uniques.html#global-uniques">&quot;[relativeAmount]% Gold cost of upgrading&quot;</a> uniques that apply.</p><h2 id="globaluniques-json" tabindex="-1">GlobalUniques.json <a class="header-anchor" href="#globaluniques-json" aria-label="Permalink to &quot;GlobalUniques.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/tree/master/android/assets/jsons/GlobalUniques.json" target="_blank" rel="noreferrer">link to original</a></p><p>GlobalUniques defines uniques that apply globally. e.g. Vanilla rulesets define the effects of Unhappiness here.</p><p>Base ruleset Mods can omit the file, in which case they inherit <a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Vanilla/GlobalUniques.json" target="_blank" rel="noreferrer">the ones from the Vanilla ruleset</a>. Alternatively, they can supply a file with an empty object (<code>{}</code>), meaning that no global Uniques exist for that Mod.</p><p>It has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>&quot;GlobalUniques&quot;</td><td>The name field is not used, but still must be set (the Ruleset validator might display it).</td></tr><tr><td>uniques</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> that apply globally</td></tr><tr><td>unitUniques</td><td>List of Strings</td><td>empty</td><td>List of <a href="./../uniques.html">unique abilities</a> that applies to each unit</td></tr></tbody></table><p>When extension rulesets define GlobalUniques, all uniques are merged. To change or remove uniques (or any other fields) set by another mod or base ruleset, use <a href="./6-MergeActions.html">Merge Actions</a> — e.g., <code>TRY_INJECT</code> for field-level modifications or <code>REMOVE_FIELD</code> to delete specific uniques.</p><h2 id="tutorials-json" tabindex="-1">Tutorials.json <a class="header-anchor" href="#tutorials-json" aria-label="Permalink to &quot;Tutorials.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/tree/master/android/assets/jsons/Tutorials.json" target="_blank" rel="noreferrer">link to original</a></p><p><strong>Note a Base Ruleset mod can define a &quot;welcome page&quot; here by adding a &quot;Tutorial&quot; with a name equal to the name of the mod!</strong> As an exception to the general rule, this file in a Base Ruleset mod will not <em>replace</em> the default, but add to it like extension mods do. Also, place it under <code>&lt;mod&gt;/jsons/</code> normally even if the original is found one level above the vanilla jsons.</p><p>Each tutorial has the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td>Entry name</td></tr><tr><td>category</td><td>String</td><td>Optional</td><td>The category where this tutorial will be displayed. &quot;Tutorials&quot; is the default.</td></tr><tr><td>civilopediaText</td><td>List</td><td>Optional</td><td>See <a href="#civilopedia-text">civilopediaText chapter</a></td></tr><tr><td>steps</td><td>List of Strings</td><td>Optional</td><td>Plain text</td></tr></tbody></table><p>If an entry contains both <code>steps</code> and <code>civilopediaText</code> attributes, the <code>civilopediaText</code> is shown first. Tutorials shown as Popup can show an show an external image (not part of the texture atlases) if there is an image unter ExtraImages (directly under assets or the Mod folder) having the same name. This is searched for, meaning the mod defining the Tutorial is irrelevant, mods can override builtin ExtraImages, and case sensitivity depends on the OS.</p><h2 id="victorytypes-json" tabindex="-1">VictoryTypes.json <a class="header-anchor" href="#victorytypes-json" aria-label="Permalink to &quot;VictoryTypes.json&quot;">​</a></h2><p><a href="https://github.com/yairm210/Unciv/tree/master/android/assets/jsons/Civ%20V%20-%20Gods%20&amp;%20Kings/VictoryTypes.json" target="_blank" rel="noreferrer">link to original</a></p><p>These files contain which victories this mod provides, and what milestones must be reached for someone to win a victory. Most of the file contains of strings that are shown to the user in the victory screen, with the rest being the requirements for winning.</p><p>Base ruleset Mods can omit the file or supply an empty list, even though at least one victory type is mandatory, in which case they inherit <a href="https://github.com/yairm210/Unciv/blob/master/android/assets/jsons/Civ%20V%20-%20Vanilla/VictoryTypes.json" target="_blank" rel="noreferrer">the ones from the Vanilla ruleset</a>.</p><p>Each victory have the following structure:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>name</td><td>String</td><td>Required</td><td>Name of the victory</td></tr><tr><td>victoryScreenHeader</td><td>String</td><td>none</td><td>Shown in the footer of the victory in the <code>our status</code> in the victory screen</td></tr><tr><td>victoryString</td><td>String</td><td>none</td><td>Shown in the footer of the victory screen when you won the game with this victory</td></tr><tr><td>defeatString</td><td>String</td><td>none</td><td>Shown in the footer of the victory screen when someone else won the game with this victory</td></tr><tr><td>hiddenInVictoryScreen</td><td>Boolean</td><td>false</td><td>Whether progress of this victory is hidden in the victory screen</td></tr><tr><td>requiredSpaceshipParts</td><td>List of Strings</td><td>empty</td><td>What spaceship parts must be added to the capital for the corresponding milestone</td></tr><tr><td>Milestones</td><td>List of Strings</td><td>Required</td><td>List of milestones that must be accomplished to win, <a href="#milestones">see below</a></td></tr><tr><td>civilopediaText</td><td>List</td><td>Optional</td><td>See <a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">civilopediaText chapter</a></td></tr></tbody></table><h3 id="milestones" tabindex="-1">Milestones <a class="header-anchor" href="#milestones" aria-label="Permalink to &quot;Milestones&quot;">​</a></h3><p>Currently the following milestones are supported:</p><table tabindex="0"><thead><tr><th>Milestone</th><th>Requirement</th></tr></thead><tbody><tr><td>Build [building]</td><td>Build the building [building] in any city</td></tr><tr><td>Anyone should build [building]</td><td>Anyone must build the building [building] for all players to have this milestone</td></tr><tr><td>Add all [comment] in capital</td><td>Add all units in the <code>requiredSpaceshipParts</code> field of this victory to the capital</td></tr><tr><td>Destroy all players</td><td>You must be the only major civilization with any cities left</td></tr><tr><td>Capture all capitals</td><td>Capture all the original capitals of major civilizations in the game</td></tr><tr><td>Complete [amount] Policy branches</td><td>Fully complete at least [amount] policy branches</td></tr><tr><td>Win diplomatic vote</td><td>At any point in the game win a diplomatic vote (UN). You may lose afterwards and still retain this milestone</td></tr><tr><td>Become the world religion</td><td>Have your religion be the majority religion in a majority of cities of all major civs</td></tr><tr><td>Have highest score after max turns</td><td>Basically time victory. Enables the &#39;max turn&#39; slider and calculates score when that amount is reached</td></tr><tr><td>Have more [countable] than each player&#39;s [countable]</td><td>Have your given <code>countable</code> be more than every other Civilization&#39;s <code>countable</code> to achieve this victory. This is useful to simulate a victory similar to the Cultural Victory in Brave New World.</td></tr></tbody></table><h2 id="civilopedia-text" tabindex="-1">Civilopedia text <a class="header-anchor" href="#civilopedia-text" aria-label="Permalink to &quot;Civilopedia text&quot;">​</a></h2><p>Any &#39;thing&#39; defined in json and listed in the Civilopedia can supply extra text, specifically for the Civilopedia. This can be used to explain special considerations better when the automatically generated display is insufficient, or for &#39;flavour&#39;, background stories and the like. Such text can be formatted and linked to other Civilopedia entries, within limits.</p><p>An example of the format is:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;civilopediaText&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ancient ruins provide a one-time random bonus when explored&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;separator&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;This line is red and links to the Scout including icons&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;link&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Unit/Scout&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;color&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;red&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;text&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A big fat header sporting a golden star&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;header&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;starred&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;color&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#ffeb7f&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><p>List of attributes - note not all combinations are valid:</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code></td><td>String</td><td>Text to display</td></tr><tr><td><code>link</code></td><td>String</td><td>Create link and icon, format: Category/Name or <em>external</em> link (&#39;http://&#39;,&#39;https://&#39;,&#39;mailto:&#39;)</td></tr><tr><td><code>icon</code></td><td>String</td><td>Show icon without linking, format: Category/Name</td></tr><tr><td><code>extraImage</code></td><td>String</td><td>Display an Image instead of text. Can be a path found in a texture atlas or or the name of a png or jpg in the ExtraImages folder</td></tr><tr><td><code>imageSize</code></td><td>Float</td><td>Size in world units of the [extraImage], the smaller coordinate is calculated preserving aspect ratio. available width</td></tr><tr><td><code>header</code></td><td>Integer</td><td>Header level. 1 means double text size and decreases from there</td></tr><tr><td><code>size</code></td><td>Integer</td><td>Text size, is 18. Use <code>size</code> or <code>header</code> but not both</td></tr><tr><td><code>indent</code></td><td>Integer</td><td>Indent level. 0 means text will follow icons, 1 aligns to the right of all icons, each further step is 30 units</td></tr><tr><td><code>padding</code></td><td>Float</td><td>Vertical padding between rows, 5 units</td></tr><tr><td><code>color</code></td><td>String</td><td>Sets text color, accepts names or 6/3-digit web colors (e.g. #FFA040)</td></tr><tr><td><code>separator</code></td><td>Boolean</td><td>Renders a separator line instead of text. Can be combined only with <code>color</code> and <code>size</code> (line width, default 2)</td></tr><tr><td><code>starred</code></td><td>Boolean</td><td>Decorates text with a star icon - if set, it receives the <code>color</code> instead of the text</td></tr><tr><td><code>centered</code></td><td>Boolean</td><td>Centers the line (and turns off automatic wrap). For an <code>extraImage</code>, turns on crop-to-content to equalize transparent borders</td></tr><tr><td><code>iconCrossed</code></td><td>Boolean</td><td>Paint a red X over the <code>icon</code> or <code>link</code> image</td></tr></tbody></table><p>The lines from json will &#39;surround&#39; the automatically generated lines such that the latter are inserted just above the first json line carrying a link, if any. If no json lines have links, they will be inserted between the automatic title and the automatic info. This method may, however, change in the future.</p><p>Note: <code>text</code> now also supports inline color markup. Insert <code>«color»</code> to start coloring text, <code>«»</code> to stop. <code>color</code> can be a name or 6/8-digit hex notation like <code>#ffa040</code> (different from the <code>color</code> attribute notation only by not allowing 3-digit codes, but allowing the alpha channel). Effectively, the <code>«»</code> markers are replaced with <code>[]</code> <em>after</em> translation and then passed to <a href="https://libgdx.com/wiki/graphics/2d/fonts/color-markup-language" target="_blank" rel="noreferrer">gdx markup language</a>.</p><p>Note: Using an ExtraImages folder in a mod was not working until version 4.11.5</p><h2 id="rgb-colors-list" tabindex="-1">RGB colors list <a class="header-anchor" href="#rgb-colors-list" aria-label="Permalink to &quot;RGB colors list&quot;">​</a></h2><p>Certain objects can be specified to have its own unique color. The colors are defined by a list of 3× Integer in this order: red, green, blue. The range of color is from [0, 0, 0] (black) to [255, 255, 255] (white).</p><p>Note: The default of some objects are <a href="https://javadoc.io/doc/com.badlogicgames.gdx/gdx/latest/com/badlogic/gdx/graphics/Color.html" target="_blank" rel="noreferrer">gdx color classes</a>. The values of the constants are as follows:</p><table tabindex="0"><thead><tr><th>name</th><th>value</th></tr></thead><tbody><tr><td>gold</td><td>[225, 215, 0]</td></tr><tr><td>white</td><td>[255, 255, 255]</td></tr><tr><td>black</td><td>[0, 0, 0]</td></tr></tbody></table>`,101)])])}const m=e(s,[["render",o]]);export{p as __pageData,m as default};
